/*
 * ardour4-prefs: Preferences Window Implementation
 * Phase 0 — GTK4/Libadwaita migration of Ardour Plus
 *
 * Maps every rc_option_editor.cc preference page to a native
 * AdwPreferencesPage + AdwPreferencesGroup with proper Adw row types.
 *
 * Config access goes through ARDOUR::RCConfiguration and
 * UIConfiguration::instance() — the same objects the GTK2 binary uses,
 * writing to the same ~/.config/ardour8/ardour.rc file.
 */

#include "prefs_window.h"

/* Generated by Meson — defines ARDOUR4_SHARED_CSS_DIR, ARDOUR4_LOCALE_DIR, etc. */
#include "ardour4_config.h"

#include <adwaita.h>
#include <glib/gi18n.h>
#include <gtk/gtk.h>

/* ── libardour / Ardour UI config headers ─────────────────────── */
#include "ardour/ardour.h"
#include "ardour/rc_configuration.h"
/* NOTE: audioengine.h is intentionally NOT included here — the prefs window
 * only reads ARDOUR::Config and UIConfiguration; it never touches the engine.
 * audioengine.h is included by main.cc, which calls ARDOUR::init(). */
#include "ui_configuration.h"

/* ── CSS loader ─────────────────────────────────────────────── */
static void
load_css (void)
{
    GtkCssProvider *provider = gtk_css_provider_new ();

    /* Load from the shared/ directory relative to the binary location.
     * During development this is the source tree path. */
    const char *src_css = ARDOUR4_SHARED_CSS_DIR "/style.css";
    gtk_css_provider_load_from_path (provider, src_css);
    gtk_style_context_add_provider_for_display (
        gdk_display_get_default (),
        GTK_STYLE_PROVIDER (provider),
        GTK_STYLE_PROVIDER_PRIORITY_APPLICATION);
    g_object_unref (provider);
}

/* ══════════════════════════════════════════════════════════════
 *  Helper macros — build Adw rows quickly
 * ══════════════════════════════════════════════════════════════ */

/* Bool: maps to AdwSwitchRow */
static AdwSwitchRow *
make_switch_row (const char *title,
                 const char *subtitle,
                 gboolean    initial)
{
    AdwSwitchRow *row = ADW_SWITCH_ROW (adw_switch_row_new ());
    adw_preferences_row_set_title (ADW_PREFERENCES_ROW (row), title);
    if (subtitle && *subtitle)
        adw_action_row_set_subtitle (ADW_ACTION_ROW (row), subtitle);
    adw_switch_row_set_active (row, initial);
    return row;
}

/* Combo: maps to AdwComboRow with a string list */
static AdwComboRow *
make_combo_row (const char  *title,
                const char  *subtitle,
                const char **items,   /* NULL-terminated */
                guint        selected)
{
    GtkStringList *sl = gtk_string_list_new (items);
    AdwComboRow   *row = ADW_COMBO_ROW (adw_combo_row_new ());
    adw_preferences_row_set_title (ADW_PREFERENCES_ROW (row), title);
    if (subtitle && *subtitle)
        adw_action_row_set_subtitle (ADW_ACTION_ROW (row), subtitle);
    adw_combo_row_set_model (row, G_LIST_MODEL (sl));
    adw_combo_row_set_selected (row, selected);
    return row;
}

/* Spin: maps to AdwSpinRow */
static AdwSpinRow *
make_spin_row (const char *title,
               const char *subtitle,
               double      min,
               double      max,
               double      step,
               double      val)
{
    GtkAdjustment *adj = gtk_adjustment_new (val, min, max, step, step * 10, 0);
    AdwSpinRow    *row = ADW_SPIN_ROW (adw_spin_row_new (adj, step, 0));
    adw_preferences_row_set_title (ADW_PREFERENCES_ROW (row), title);
    if (subtitle && *subtitle)
        adw_action_row_set_subtitle (ADW_ACTION_ROW (row), subtitle);
    return row;
}

/* Entry: maps to AdwEntryRow */
static AdwEntryRow *
make_entry_row (const char *title, const char *initial_text)
{
    AdwEntryRow *row = ADW_ENTRY_ROW (adw_entry_row_new ());
    adw_preferences_row_set_title (ADW_PREFERENCES_ROW (row), title);
    if (initial_text && *initial_text)
        gtk_editable_set_text (GTK_EDITABLE (row), initial_text);
    return row;
}


/* ══════════════════════════════════════════════════════════════
 *  PAGE: General
 * ══════════════════════════════════════════════════════════════ */
AdwPreferencesPage *
ardour_prefs_page_general (void)
{
    AdwPreferencesPage *page = ADW_PREFERENCES_PAGE (adw_preferences_page_new ());
    adw_preferences_page_set_title (page, _("General"));
    adw_preferences_page_set_icon_name (page, "preferences-system-symbolic");

    ARDOUR::RCConfiguration *cfg = ARDOUR::Config;

    /* ── Group: Session Management ─── */
    AdwPreferencesGroup *g_session = ADW_PREFERENCES_GROUP (adw_preferences_group_new ());
    adw_preferences_group_set_title (g_session, _("Session Management"));
    adw_preferences_group_set_description (g_session,
        _("Control how Ardour handles sessions at startup and shutdown."));

    adw_preferences_group_add (g_session, GTK_WIDGET (make_switch_row (
        _("Auto-connect to session on startup"),
        _("Automatically connect master bus outputs when creating a new session"),
        cfg->get_auto_connect_standard_busses ())));

    adw_preferences_group_add (g_session, GTK_WIDGET (make_switch_row (
        _("Only close dialog on \"Close Session\""),
        _("Prevent accidental session close from the window close button"),
        false)));

    adw_preferences_group_add (g_session, GTK_WIDGET (make_spin_row (
        _("Maximum recent sessions"), NULL,
        0, 50, 1,
        cfg->get_max_recent_sessions ())));

    adw_preferences_page_add (page, g_session);

    /* ── Group: Editor Undo ─── */
    AdwPreferencesGroup *g_undo = ADW_PREFERENCES_GROUP (adw_preferences_group_new ());
    adw_preferences_group_set_title (g_undo, _("Editor Undo"));

    adw_preferences_group_add (g_undo, GTK_WIDGET (make_switch_row (
        _("Limit undo history"),
        _("Cap the number of undo steps kept in memory"),
        (cfg->get_history_depth () > 0))));

    adw_preferences_group_add (g_undo, GTK_WIDGET (make_spin_row (
        _("Undo history depth"), _("Number of undo steps to keep"),
        1, 500, 1,
        cfg->get_history_depth ())));

    adw_preferences_group_add (g_undo, GTK_WIDGET (make_switch_row (
        _("Save undo history with session"),
        _("Restore undo history when re-opening a session"),
        cfg->get_save_history ())));

    adw_preferences_page_add (page, g_undo);

    /* ── Group: Import ─── */
    AdwPreferencesGroup *g_import = ADW_PREFERENCES_GROUP (adw_preferences_group_new ());
    adw_preferences_group_set_title (g_import, _("Import"));

    adw_preferences_group_add (g_import, GTK_WIDGET (make_switch_row (
        _("Drag-and-drop creates regions"),
        _("When unchecked, drag-and-drop always opens the import dialog"),
        UIConfiguration::instance().get_only_copy_imported_files ())));

    adw_preferences_group_add (g_import, GTK_WIDGET (make_switch_row (
        _("Automatic analysis of audio"),
        _("Compute transients and loudness in the background after import"),
        cfg->get_auto_analyse_audio ())));

    adw_preferences_page_add (page, g_import);

    /* ── Group: Export ─── */
    AdwPreferencesGroup *g_export = ADW_PREFERENCES_GROUP (adw_preferences_group_new ());
    adw_preferences_group_set_title (g_export, _("Export"));

    adw_preferences_group_add (g_export, GTK_WIDGET (make_switch_row (
        _("Save loudness analysis with session"),
        NULL,
        UIConfiguration::instance().get_save_export_mixer_screenshot ())));

    adw_preferences_group_add (g_export, GTK_WIDGET (make_switch_row (
        _("Open export folder when done"),
        NULL,
        false)));

    adw_preferences_page_add (page, g_export);

    /* ── Group: Updates ─── */
    AdwPreferencesGroup *g_update = ADW_PREFERENCES_GROUP (adw_preferences_group_new ());
    adw_preferences_group_set_title (g_update, _("Updates"));

    adw_preferences_group_add (g_update, GTK_WIDGET (make_switch_row (
        _("Check for new Ardour versions on startup"),
        NULL,
        false)));

    adw_preferences_page_add (page, g_update);

    return page;
}


/* ══════════════════════════════════════════════════════════════
 *  PAGE: Appearance
 * ══════════════════════════════════════════════════════════════ */
AdwPreferencesPage *
ardour_prefs_page_appearance (void)
{
    AdwPreferencesPage *page = ADW_PREFERENCES_PAGE (adw_preferences_page_new ());
    adw_preferences_page_set_title (page, _("Appearance"));
    adw_preferences_page_set_icon_name (page, "applications-graphics-symbolic");

    ARDOUR::RCConfiguration *cfg = ARDOUR::Config;

    /* ── Group: Theme ─── */
    AdwPreferencesGroup *g_theme = ADW_PREFERENCES_GROUP (adw_preferences_group_new ());
    adw_preferences_group_set_title (g_theme, _("Theme"));

    /* color_file contains the theme name; dark if it contains "dark" */
    bool is_dark = (UIConfiguration::instance().get_color_file().find("dark") != std::string::npos);
    adw_preferences_group_add (g_theme, GTK_WIDGET (make_switch_row (
        _("Use dark theme"),
        NULL,
        is_dark)));

    adw_preferences_group_add (g_theme, GTK_WIDGET (make_switch_row (
        _("Draw region name on waveform"),
        NULL,
        UIConfiguration::instance().get_show_region_names ())));

    adw_preferences_page_add (page, g_theme);

    /* ── Group: Size & Scale ─── */
    AdwPreferencesGroup *g_scale = ADW_PREFERENCES_GROUP (adw_preferences_group_new ());
    adw_preferences_group_set_title (g_scale, _("Size and Scale"));
    adw_preferences_group_set_description (g_scale,
        _("Applies immediately. Restart may be required for some elements."));

    adw_preferences_group_add (g_scale, GTK_WIDGET (make_spin_row (
        _("GUI scale factor"), _("Multiplier applied to all UI element sizes"),
        50, 400, 5,
        /* font_scale is stored in 1024ths — convert to percent */
        (double)(UIConfiguration::instance().get_font_scale()) / 10.24)));

    /* DPI override: UIConfig has no single toggle; use a placeholder for now */
    (void)cfg;  /* suppress unused warning */

    adw_preferences_page_add (page, g_scale);

    /* ── Group: Toolbar ─── */
    AdwPreferencesGroup *g_toolbar = ADW_PREFERENCES_GROUP (adw_preferences_group_new ());
    adw_preferences_group_set_title (g_toolbar, _("Main Toolbar"));

    adw_preferences_group_add (g_toolbar, GTK_WIDGET (make_switch_row (
        _("Show secondary clock"), NULL,
        UIConfiguration::instance().get_show_secondary_clock ())));

    adw_preferences_group_add (g_toolbar, GTK_WIDGET (make_switch_row (
        _("Show Selection info in toolbar"), NULL,
        UIConfiguration::instance().get_show_toolbar_selclock ())));

    adw_preferences_group_add (g_toolbar, GTK_WIDGET (make_switch_row (
        _("Show Monitor Section info in toolbar"), NULL,
        UIConfiguration::instance().get_show_toolbar_monitor_info ())));

    adw_preferences_group_add (g_toolbar, GTK_WIDGET (make_switch_row (
        _("Super-rapid clock update"),
        _("Refresh transport clocks at the highest available rate"),
        UIConfiguration::instance().get_super_rapid_clock_update ())));

    adw_preferences_page_add (page, g_toolbar);

    return page;
}


