/* ══════════════════════════════════════════════════════════════
 *  PAGE: Control Surfaces
 * ══════════════════════════════════════════════════════════════ */
AdwPreferencesPage *
ardour_prefs_page_surfaces (void)
{
    AdwPreferencesPage *page = ADW_PREFERENCES_PAGE (adw_preferences_page_new ());
    adw_preferences_page_set_title (page, _("Control Surfaces"));
    adw_preferences_page_set_icon_name (page, "input-gaming-symbolic");

    AdwPreferencesGroup *g = ADW_PREFERENCES_GROUP (adw_preferences_group_new ());
    adw_preferences_group_set_title (g, _("Available Surfaces"));
    adw_preferences_group_set_description (g,
        _("Enable or disable hardware control surface support. "
          "Surface-specific options appear when a surface is enabled."));

    /* Enumerate discovered protocols from ControlProtocolManager */
    /* NOTE: Full implementation will iterate ControlProtocolManager::instance().control_protocol_info
     * For Phase 0 we show representative surfaces as placeholders */
    const char *surfaces[] = {
        "Mackie Control Universal", "Open Sound Control (OSC)",
        "PreSonus FaderPort", "Generic MIDI", NULL
    };
    for (int i = 0; surfaces[i]; ++i) {
        AdwSwitchRow *row = ADW_SWITCH_ROW (adw_switch_row_new ());
        adw_preferences_row_set_title (ADW_PREFERENCES_ROW (row), surfaces[i]);
        adw_switch_row_set_active (row, FALSE);
        adw_preferences_group_add (g, GTK_WIDGET (row));
    }

    adw_preferences_page_add (page, g);
    return page;
}


/* ══════════════════════════════════════════════════════════════
 *  PAGE: Video
 * ══════════════════════════════════════════════════════════════ */
AdwPreferencesPage *
ardour_prefs_page_video (void)
{
    AdwPreferencesPage *page = ADW_PREFERENCES_PAGE (adw_preferences_page_new ());
    adw_preferences_page_set_title (page, _("Video"));
    adw_preferences_page_set_icon_name (page, "video-display-symbolic");

    ARDOUR::RCConfiguration *cfg = ARDOUR::Config;

    AdwPreferencesGroup *g = ADW_PREFERENCES_GROUP (adw_preferences_group_new ());
    adw_preferences_group_set_title (g, _("Video Server"));

    adw_preferences_group_add (g, GTK_WIDGET (make_entry_row (
        _("Video server URL"),
        cfg->get_video_server_url ().c_str ())));

    adw_preferences_group_add (g, GTK_WIDGET (make_switch_row (
        _("Include video in export"),
        NULL,
        cfg->get_video_advanced_setup ())));

    adw_preferences_page_add (page, g);
    return page;
}


/* ══════════════════════════════════════════════════════════════
 *  PAGE: Performance
 * ══════════════════════════════════════════════════════════════ */
AdwPreferencesPage *
ardour_prefs_page_performance (void)
{
    AdwPreferencesPage *page = ADW_PREFERENCES_PAGE (adw_preferences_page_new ());
    adw_preferences_page_set_title (page, _("Performance"));
    adw_preferences_page_set_icon_name (page, "utilities-system-monitor-symbolic");

    ARDOUR::RCConfiguration *cfg = ARDOUR::Config;

    AdwPreferencesGroup *g_disk = ADW_PREFERENCES_GROUP (adw_preferences_group_new ());
    adw_preferences_group_set_title (g_disk, _("Disk I/O Buffering"));

    adw_preferences_group_add (g_disk, GTK_WIDGET (make_spin_row (
        _("Playback buffer size"), _("Seconds of audio to buffer from disk"),
        1, 120, 1,
        cfg->get_audio_playback_buffer_seconds ())));

    adw_preferences_group_add (g_disk, GTK_WIDGET (make_spin_row (
        _("Record buffer size"), _("Seconds of audio to buffer before writing to disk"),
        1, 120, 1,
        cfg->get_audio_capture_buffer_seconds ())));

    adw_preferences_page_add (page, g_disk);

    AdwPreferencesGroup *g_cpu = ADW_PREFERENCES_GROUP (adw_preferences_group_new ());
    adw_preferences_group_set_title (g_cpu, _("CPU"));

    adw_preferences_group_add (g_cpu, GTK_WIDGET (make_switch_row (
        _("Denormal handling"),
        _("Flush floating-point denormals to zero (reduces CPU spikes)"),
        cfg->get_denormal_protection ())));

    adw_preferences_group_add (g_cpu, GTK_WIDGET (make_switch_row (
        _("Use hardware optimisation"),
        _("Use SSE/AVX when available for DSP operations"),
        TRUE   /* set by try_hw_optimization at init time */)));

    adw_preferences_page_add (page, g_cpu);

    return page;
}


/* ══════════════════════════════════════════════════════════════
 *  Main window assembly
 * ══════════════════════════════════════════════════════════════ */
GtkWidget *
ardour_prefs_window_new (AdwApplication *app)
{
    load_css ();

    AdwPreferencesWindow *win = ADW_PREFERENCES_WINDOW (adw_preferences_window_new ());
    gtk_window_set_application (GTK_WINDOW (win), GTK_APPLICATION (app));
    gtk_window_set_title (GTK_WINDOW (win), _("Ardour Preferences"));
    gtk_window_set_default_size (GTK_WINDOW (win), 900, 680);

    /* Search is built into AdwPreferencesWindow — no extra work needed */
    adw_preferences_window_set_search_enabled (win, TRUE);

    /* Add every page */
    adw_preferences_window_add (win, ardour_prefs_page_general ());
    adw_preferences_window_add (win, ardour_prefs_page_appearance ());
    adw_preferences_window_add (win, ardour_prefs_page_editor ());
    adw_preferences_window_add (win, ardour_prefs_page_mixer ());
    adw_preferences_window_add (win, ardour_prefs_page_transport ());
    adw_preferences_window_add (win, ardour_prefs_page_midi ());
    adw_preferences_window_add (win, ardour_prefs_page_plugins ());
    adw_preferences_window_add (win, ardour_prefs_page_surfaces ());
    adw_preferences_window_add (win, ardour_prefs_page_video ());
    adw_preferences_window_add (win, ardour_prefs_page_performance ());

    return GTK_WIDGET (win);
}
